METALS = [
    ("jaune", "Or jaune", "#e3c26f", 0),
    ("blanc", "Or blanc", "#dcdcd8", 1),
    ("rose", "Or rose", "#e8a98f", 2),
    ("bicolore", "Bicolore", "linear-gradient(90deg,#e3c26f 50%,#dcdcd8 50%)", 3),
]


def create_metals(apps, schema_editor):
    Metal = apps.get_model("catalog", "Metal")
    Ring = apps.get_model("catalog", "Ring")
    for code, name, swatch, position in METALS:
        Metal.objects.get_or_create(code=code, defaults={"name": name, "swatch": swatch, "position": position})
    for ring in Ring.objects.all():
        ring.metals.add(Metal.objects.get(code=ring.color))


Migration.operations.append(migrations.RunPython(create_metals, migrations.RunPython.noop))
